<script lang="ts">
 import {onMount} from 'svelte';import {enter} from './motion';import {api} from './api';import type {Row} from './types';
 let {company,kind,options,oncreated,onclose}:{company:number;kind:string;options:Row[];oncreated:(result:Row)=>Promise<void>;onclose:()=>void}=$props();
 let dialog:HTMLDialogElement,origin=$state('India'),profile:Record<string,string>=$state({category:'',weave:'',composition:'',color:''}),busy=$state(false),error=$state('');
 const fields=[['category','Category'],['weave','Weave'],['composition','Composition'],['color','Colour']];
 onMount(()=>dialog.showModal());
 async function save(e:SubmitEvent){e.preventDefault();if(busy)return;busy=true;error='';try{const result=await api('/material-references',{company_id:company,kind,origin,profile});await oncreated(result)}catch(e){error=(e as Error).message}finally{busy=false}}
</script>
<dialog bind:this={dialog} aria-labelledby="merchant-material-title" oncancel={e=>{if(busy)e.preventDefault();else onclose()}} use:enter><form onsubmit={save}><header><h2 id="merchant-material-title">ETF/ESF Generate</h2><button type="button" disabled={busy} onclick={onclose}>Close</button></header><div class="body"><p>Generate a {kind} material with its permanent number. Sourcing will add the supplier and complete the private details before it can be used.</p><label>Reference registered in<select bind:value={origin}><option value="India">India — ESF</option><option value="Dubai">Dubai — ETF</option></select></label><div class="fields">{#each fields as [key,title]}<label>{title}<select bind:value={profile[key]} onchange={()=>{if(key==='category')profile.weave=''}}><option value="">Sourcing will complete this</option>{#each options.filter(o=>o.company_id===company&&o.kind===key&&o.active&&(key!=='weave'||String(o.parent_id)===profile.category)) as o}<option value={String(o.id)}>{o.label}</option>{/each}</select></label>{/each}</div><p class="help">The generated material appears in your library as Awaiting Sourcing. Supplier identities and documents stay private.</p>{#if error}<p class="error" role="alert">{error}</p>{/if}</div><footer><button type="button" disabled={busy} onclick={onclose}>Cancel</button><button class="primary" disabled={busy}>{busy?'Generating…':'Generate ETF/ESF'}</button></footer></form></dialog>
<style>dialog{width:min(800px,calc(100vw - 40px));max-height:calc(100dvh - 40px);padding:0;border:1px solid #b6c5ce;border-radius:10px;color:#111;background:white}dialog::backdrop{background:#10263699}form{display:flex;flex-direction:column;max-height:calc(100dvh - 40px)}header{display:flex;align-items:center;justify-content:space-between;gap:16px;background:#132b40;color:white;padding:14px 20px}h2{color:white;margin:0;font-size:19px}.body{padding:16px 20px;overflow:auto}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 16px;margin-top:16px}label{display:grid;gap:6px;font-size:13px;font-weight:600;color:#111}select{min-height:44px;padding:10px;border:1px solid #b6c5ce;border-radius:6px;background:#f2f8f8;color:#111;font:inherit}p{line-height:1.5;margin:0 0 16px}.help{font-size:13px;color:#374151;margin:16px 0 0}.error{color:#a12624;margin:12px 0 0}footer{display:flex;justify-content:flex-end;gap:12px;padding:12px 20px;border-top:1px solid #b6c5ce}button{min-height:44px;padding:10px 16px;border:1px solid #b6c5ce;border-radius:6px;background:white;color:#132b40;font:inherit;cursor:pointer}.primary{background:#087f83;color:white;border-color:#087f83}button:disabled{cursor:default;opacity:.7}</style>
